    //! Private
const std::string& Zia::Json::Array::getIndex(size_t index) const
{
    static std::string res("");
    size_t counter = 0;

    res = "";
    try {
        if (index > _json.size())
            return res;
        for (auto el : _json.items()) {
            if (counter == index)
                break;
            res = el.key();
            counter++;
        }
        return res;
    } catch(...) {
        return res;
    }
}

